INSERT INTO Writes_and_Receives_Review (Review_ID, User_ID, Restaurant_ID, Review_Date, Rating, Rating_text) VALUES
(801, 1, 101, '2026-10-11', 5, 'Great coffee and pastries.'),
(802, 2, 102, '2026-10-11', 4, 'Nice brunch spot, slightly crowded.'),
(803, 3, 103, '2026-10-12', 5, 'Vibrant atmosphere and excellent food.'),
(804, 4, 104, '2026-10-12', 3, 'Convenient, but the BBQ was dry.'),
(805, 5, 105, '2026-10-13', 5, 'Fantastic French cuisine, highly recommend.'),
(806, 6, 106, '2026-10-13', 5, 'Incredible omakase experience.'),
(807, 7, 107, '2026-10-14', 4, 'Giant slices, good late-night option.'),
(808, 8, 108, '2026-10-14', 3, 'Standard diner food, open 24/7 is a plus.'),
(809, 9, 109, '2026-10-15', 4, 'Authentic Greek, massive portions.'),
(810, 10, 110, '2026-10-15', 5, 'Perfect medium-rare steak.'),
(811, 11, 111, '2026-10-16', 4, 'Broth was rich, noodles were fresh.'),
(812, 12, 112, '2026-10-16', 5, 'Best al pastor tacos in Midtown.'),
(813, 13, 113, '2026-10-17', 4, 'Solid curry, good spice level.'),
(814, 14, 114, '2026-10-17', 5, 'Delicious vegan options, didn''t miss the meat!'),
(815, 15, 115, '2026-10-18', 4, 'Fun tapas, great sangria.'),
(816, 16, 116, '2026-10-18', 5, 'Classic brasserie feel, excellent service.'),
(817, 17, 117, '2026-10-19', 4, 'Solid BEC sandwich.'),
(818, 18, 118, '2026-10-19', 5, 'The oysters were incredibly fresh.'),
(819, 19, 119, '2026-10-20', 4, 'Great dim sum, cart service is fun.'),
(820, 20, 120, '2026-10-20', 3, 'Burger was okay, fries were cold.'),
(821, 21, 121, '2026-10-21', 5, 'Cheap and amazing soup dumplings.'),
(822, 22, 122, '2026-10-21', 4, 'Good cold brew, quiet spot to work.'),
(823, 23, 123, '2026-10-22', 5, 'Handmade pasta was phenomenal.'),
(824, 24, 124, '2026-10-22', 4, 'Quick pastrami sandwich, gets the job done.'),
(825, 25, 125, '2026-10-22', 5, 'The fried chicken and waffles are a must.');
